export function createDns({ address = '10.60', ttlTicks = 300, records = { 'example.com': '10.1' } } = {}) {
  // validate mini-IP, ttlTicks integer >= 1
  const cache = new Map(); // name -> { name, target, expiresAtTick }
  let lookups = 0, cachedHits = 0, authoritative = 0;
  let lastLookup = null;
  function lookup(name, currentTick = 0) {
    lookups += 1;
    const entry = cache.get(name);
    if (entry && currentTick < entry.expiresAtTick) {
      cachedHits += 1;
      lastLookup = { name, status: 'HIT', target: entry.target, atTick: currentTick };
      return { status: 'OK', target: entry.target, cacheStatus: 'HIT' };
    }
    if (entry) cache.delete(name); // expired entry dropped, never answered from ledger
    const target = records[name] ?? null;
    authoritative += 1;
    if (target === null) {
      lastLookup = { name, status: 'NX', atTick: currentTick };
      return { status: 'NX', target: null, cacheStatus: 'MISS' };
    }
    cache.set(name, { name, target, expiresAtTick: currentTick + ttlTicks });
    lastLookup = { name, status: 'MISS', target, atTick: currentTick };
    return { status: 'OK', target, cacheStatus: 'MISS' };
  }
  snapshot(currentTick) → { address, ttlTicks, lookups, cachedHits, authoritative, lastLookup, cache: [...] with ttlRemaining }
}
```

