describe('createRng', () => {
  it('is deterministic per seed and differs across seeds', () => {
    const a = Array.from({ length: 10 }, createRng(7));
    const b = Array.from({ length: 10 }, createRng(7));
    const c = Array.from({ length: 10 }, createRng(8));
    expect(a).toEqual(b);
