// DOCUMENTS: a round-robin load balancer at a public mini-IP (default 10.1).
// Holds an ordered list of backend server mini-IPs (e.g. ['10.11', '10.12'])
// and a cursor `nextIndex`. Each incoming request selects
// `backends[nextIndex]`, advances `nextIndex = (nextIndex + 1) % backends.length`,
// and forwards the request across the network to that backend's queue or
// synchronous handler.
//
// CHECKS: constructor rejects an invalid mini-IP address or an empty /
// malformed backend pool so misconfigured topologies fail loud at boot.
const MINI_IP = /^\d+\.\d+$/;

export function createLoadBalancer({
  address = '10.1',
  backends = ['10.11', '10.12'],
  network = null,
} = {}) {
  if (!MINI_IP.test(address)) {
    throw new Error(`loadbalancer: invalid mini-IP address ${address}`);
  }
  if (
    !Array.isArray(backends) ||
    backends.length === 0 ||
    !backends.every((b) => MINI_IP.test(b))
  ) {
    throw new Error('loadbalancer: backends must be a non-empty list of <net>.<host> addresses');
  }
  const pool = [...backends];
  const perBackend = Object.fromEntries(pool.map((b) => [b, 0]));
  let nextIndex = 0;
  let forwarded = 0;
  let lastTarget = null;

  function selectBackend() {
    const target = pool[nextIndex];
    nextIndex = (nextIndex + 1) % pool.length;
    forwarded += 1;
    perBackend[target] += 1;
    lastTarget = target;
    return target;
  }

  return {
    get address() {
      return address;
    },

    get backends() {
      return [...pool];
    },

    nextBackend() {
      return pool[nextIndex];
    },

    selectBackend,

    handleRequest(request = 'GET /') {
      if (!network) throw new Error('loadbalancer: no network attached');
      const target = selectBackend();
      return network.send({ from: address, to: target, request }).response;
    },

    enqueue({ id, atTick, from = '10.2', request = 'GET /', isYou = false }) {
      if (!network) throw new Error('loadbalancer: no network attached');
      const target = selectBackend();
      network.deliverToQueue({ id, from, to: target, request, atTick, isYou });
      return target;
    },

    snapshot() {
      return {
        address,
        algorithm: 'round-robin',
        backends: [...pool],
        nextBackend: pool[nextIndex],
        forwarded,
        lastTarget,
        perBackend: { ...perBackend },
      };
    },
  };
}
// DOCUMENTS: a simulated browser — builds slim HTTP requests ("GET /path"),
// parses slim responses ("<status> <body>"), and sends them across the
// network to a target mini-IP. The newest displayed exchange is kept as
// inspectable state (`last()`), the way a browser keeps a rendered page.
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP (<net>.<host>) — fail-loud over silent mis-addressing.
export function createBrowser({ name = 'Browser-1', address = '10.2', network = null } = {}) {
  if (!/^\d+\.\d+$/.test(address)) {
    throw new Error(`browser: address must be <net>.<host>, got ${address}`);
  }
  let lastDisplay = null;

  return {
    get name() {
      return name;
    },
    get address() {
      return address;
    },

    // Slimmed-down HTTP: the stack rules cut every token that does not
    // earn a teaching place (AGENTS.md). The learner picks the method in
    // the mini-browser; GET stays the default for every crowd path.
    createRequest(path = '/', method = 'GET') {
      return `${method} ${path}`;
    },

    parseResponse(raw) {
      const [statusToken, ...bodyParts] = String(raw).trim().split(' ');
      return { status: Number(statusToken), body: bodyParts.join(' ') };
    },

    // Render an exchange that arrived as a wire record (the engine's
    // hop-by-hop trace delivers it here): parse and store as inspectable
    // viewport state.
    receiveResponse({ from, to, request, response }) {
      const { status, body } = this.parseResponse(response);
      lastDisplay = { from, to, request, response, status, body };
      return lastDisplay;
    },

    get(targetAddress, path = '/', method = 'GET') {
      if (!network) throw new Error('browser: no network attached');
      const request = this.createRequest(path, method);
      const { response } = network.send({ from: address, to: targetAddress, request });
      return this.receiveResponse({ from: address, to: targetAddress, request, response });
    },

    last() {
      return lastDisplay;
    },
  };
}
// DOCUMENTS: N simulated users — each tick, each user emits at most one
// request with probability `arrivalProb`, drawn from the engine's seeded
// RNG (passed in; this module holds no randomness of its own, so count
