createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  const records = { 'example.com': '10.1' };  // authoritative table (6b adds the CDN name)
  const cache = new Map();  // name -> { target, expiresAtTick }
  let lookups = 0, cachedHits = 0, authoritative = 0, lastLookup = null;
  function lookup(name, currentTick = 0) {
    lookups += 1;
    const entry = cache.get(name);
    if (entry && currentTick < entry.expiresAtTick) {  // live entry: no table consult
      cachedHits += 1;
      lastLookup = { name, status: 'HIT', target: entry.target, atTick: currentTick };
      return { status: 'OK', target: entry.target, cacheStatus: 'HIT' };
    }
    if (entry) cache.delete(name);  // expired: never answered from the ledger
    authoritative += 1;
    const target = records[name] ?? null;
    if (target === null) {  // unknown name: NX, never a throw
      lastLookup = { name, status: 'NX', atTick: currentTick };
      return { status: 'NX' };
    }
    cache.set(name, { name, target, expiresAtTick: currentTick + ttlTicks });
    lastLookup = { name, status: 'MISS', target, atTick: currentTick };
    return { status: 'OK', target, cacheStatus: 'MISS' };
  }
  function snapshot(currentTick = 0) {
    return { address, ttlTicks, lookups, cachedHits, authoritative, lastLookup,
      cache: [...cache.values()].map((e) => ({ ...e, ttlRemaining: e.expiresAtTick - currentTick })) };
  }
  return { address getter, lookup, snapshot };
}
