    return {
      hop: 0,
      method: 'GET',
      path: '/about',
      from: '10.2',
      request: 'GET /about',
      displayRequest: 'GET /about',
      host: null,
      dnsStatus: null,
      dnsCacheStatus: null,
      dnsTarget: null,
      totalHops: null,
      targetServer: null,
      cacheStatus: null,
      dbOp: null,
      dbStale: false,
      response: null,
      status: null,
      body: null,
      routeId: null,
    };
