import { describe, it, expect } from 'vitest';
import { createDns } from '../../js/sim/dns.js';
import { createEngine } from '../../js/sim/engine.js';

describe('createDns', () => {
  // PINS: the DNS TTL branch — a lookup inside ttlTicks is an incrementing
  // cachedHits with NO authoritative consult; an expired entry is dropped
  // and the table is re-consulted, never answered from the ledger.
  it('answers a lookup inside ttlTicks from the ledger cache with no authoritative consult', () => {
    const dns = createDns({ address: '10.60', ttlTicks: 300 });

    // First lookup: a real table consult (authoritative), which fills the
    // ledger with the tick-TTL entry.
    expect(dns.lookup('example.com', 5)).toEqual({
      status: 'OK',
      target: '10.1',
      cacheStatus: 'MISS',
    });
    let snap = dns.snapshot(5);
    expect(snap).toMatchObject({ lookups: 1, cachedHits: 0, authoritative: 1 });
    expect(snap.cache).toEqual([
      { name: 'example.com', target: '10.1', expiresAtTick: 305, ttlRemaining: 300 },
    ]);

    // Inside the TTL: the ledger answers — cachedHits increments and the
    // authoritative counter must NOT move.
    expect(dns.lookup('example.com', 304)).toEqual({
      status: 'OK',
      target: '10.1',
      cacheStatus: 'HIT',
    });
    snap = dns.snapshot(304);
    expect(snap).toMatchObject({ lookups: 2, cachedHits: 1, authoritative: 1 });
    expect(snap.lastLookup).toEqual({
      name: 'example.com',
      status: 'HIT',
      target: '10.1',
      atTick: 304,
    });
  });

  it('never answers an expired entry from the cache ledger and reconsults the table', () => {
    const dns = createDns({ address: '10.60', ttlTicks: 300 });

    dns.lookup('example.com', 0); // cached at tick 0, alive through 299
    // Tick 300 is the first tick the entry is gone: the ledger must not
    // answer — the table is re-consulted (authoritative +1) and the entry
    // is rewritten with a fresh expiry.
    expect(dns.lookup('example.com', 300)).toEqual({
      status: 'OK',
      target: '10.1',
      cacheStatus: 'MISS',
    });
    const snap = dns.snapshot(300);
    expect(snap).toMatchObject({ lookups: 2, cachedHits: 0, authoritative: 2 });
    expect(snap.cache).toEqual([
      { name: 'example.com', target: '10.1', expiresAtTick: 600, ttlRemaining: 300 },
    ]);
  });

  // PINS: the unknown-name branch — NX, not a throw; the DNS layer never
  // throws on a missing record (the throw rule belongs to cross-subnet
  // addresses, network.js).
  it('answers an unknown name with NX no record and never throws', () => {
    const dns = createDns({ address: '10.60', ttlTicks: 300 });
    expect(dns.lookup('nope.example', 1)).toEqual({ status: 'NX' });
    const snap = dns.snapshot(1);
    expect(snap).toMatchObject({ lookups: 1, cachedHits: 0, authoritative: 1 });
    expect(snap.cache).toEqual([]);
    expect(snap.lastLookup).toEqual({ name: 'nope.example', status: 'NX', atTick: 1 });
  });

  // CHECKS: the constructor rejects a non-mini-IP address and a
  // non-positive or non-integer ttlTicks (fail-loud over silent misconfig).
  it('rejects a non mini-IP address and a non-positive ttlTicks', () => {
    expect(() => createDns({ address: '1060' })).toThrow(/invalid mini-IP/);
    expect(() => createDns({ ttlTicks: 0 })).toThrow(/ttlTicks/);
    expect(() => createDns({ ttlTicks: 2.5 })).toThrow(/ttlTicks/);
  });
});

describe('stage 6 engine wiring', () => {
  // PINS: stage >= 6 instantiates DNS 10.60 with a 300t TTL ledger and the
  // Router 10.65 ⇄ 20.1, both exposed on the snapshot; earlier stages
  // expose neither.
  it('stage 6 engine exposes DNS 10.60 and Router 10.65 ⇄ 20.1 on the snapshot', () => {
    const engine = createEngine({ stage: 6 });
    const snap = engine.snapshot();
    expect(snap.dns).toMatchObject({ address: '10.60', ttlTicks: 300, lookups: 0 });
    expect(snap.router).toEqual({
      leftAddress: '10.65',
      rightAddress: '20.1',
      routed: 0,
      lastHop: null,
    });
    expect(createEngine({ stage: 5 }).snapshot().dns).toBe(null);
    expect(createEngine({ stage: 5 }).snapshot().router).toBe(null);
    expect(() => createEngine({ stage: 7 })).toThrow(/stage must be/);
  });
});

import { describe, it, expect } from 'vitest';
import { createNetwork } from '../../js/sim/network.js';
import { createRouter } from '../../js/sim/router.js';
import { createWebServer } from '../../js/sim/webserver.js';
import { createBrowser } from '../../js/sim/browser.js';

describe('createRouter', () => {
  // PINS: same-subnet sends are unchanged from today's send/deliverToQueue
  // contract — the router attaches as a gateway but never sees a frame
  // whose destination lives on the sending side's own subnet.
  it('passes same-subnet sends through unchanged with no router hop', () => {
    const left = createNetwork();
    const right = createNetwork();
    const router = createRouter({ leftAddress: '10.65', rightAddress: '20.1' });
    router.join(left, right);
    const server = createWebServer({ address: '10.1' });
    left.registerServer('10.1', server);

    const browser = createBrowser({ address: '10.2', network: left });
    const ok = browser.get('10.1', '/about');
    expect(ok.response).toBe('200 This is the about page');
    expect(router.snapshot()).toMatchObject({ routed: 0, lastHop: null });
  });

  // PINS: a cross-subnet frame takes exactly one router hop, forwarded from
  // the router's own interface on the far side; the router answers its own
  // right-side interface, so 20.1 is the only reachable 20.x target in 6a.
  it('takes a cross-subnet frame over exactly one router hop to 20.1', () => {
    const left = createNetwork();
    const right = createNetwork();
    const router = createRouter({ leftAddress: '10.65', rightAddress: '20.1' });
    router.join(left, right);
    right.registerServer('20.1', router);

    const record = left.send({ from: '10.2', to: '20.1', request: 'GET /' });
    expect(record).toEqual({
      from: '10.2',
      to: '20.1',
      request: 'GET /',
      response: '200 Router at 20.1',
    });
    expect(router.snapshot()).toMatchObject({
      routed: 1,
      lastHop: { from: '10.2', via: '20.1', to: '20.1', request: 'GET /' },
    });

    // The reverse direction routes back through the left interface (10.65).
    const server = createWebServer({ address: '10.1' });
    left.registerServer('10.1', server);
    const back = right.send({ from: '20.1', to: '10.1', request: 'GET /about' });
    expect(back.response).toBe('200 This is the about page');
    expect(router.snapshot().routed).toBe(2);
  });

  // PINS: the DL-1 fail-loud counter-example — sending into subnet 20 to an
  // unregistered host (20.9) throws, mirroring network.js's own
  // `no server at` failure for same-subnet sends.
  it('fails loud sending into subnet 20 to an unregistered host like 20.9', () => {
    const left = createNetwork();
    const right = createNetwork();
    const router = createRouter({ leftAddress: '10.65', rightAddress: '20.1' });
    router.join(left, right);

    expect(() => left.send({ from: '10.2', to: '20.9', request: 'GET /' })).toThrow(
      /no server at 20\.9/,
    );
    // Nothing was routed — the throw happens before the hop counts.
    expect(router.snapshot().routed).toBe(0);
  });

  // CHECKS: the constructor rejects a non-mini-IP interface and a
  // same-subnet pair (both interfaces on one subnet join nothing).
  it('rejects invalid or same-subnet interface addresses', () => {
    expect(() => createRouter({ leftAddress: '1065' })).toThrow(/invalid mini-IP/);
    expect(() => createRouter({ rightAddress: '201' })).toThrow(/invalid mini-IP/);
    expect(() => createRouter({ leftAddress: '10.65', rightAddress: '10.1' })).toThrow(
      /different subnets/,
    );
  });
});

