// round-robin pick), 6 in Stage 3 (cache check, then response emit), 7 in
// Stage 4 (the database hop after the cache check), 8 in Stage 5 (the
// async worker tail).
//
// The Stage 5 chain sentences are built parameterized by the hop total so
// Stage 6 can reuse them verbatim: a host-less Stage 6 path passes total=8
// and gets the byte-identical Stage 5 sentences, a hosted path passes
// total=10 and splices the two DNS hops in after the emit.
function stage5Chain(t, snapshot, from, serverAddress, target, total = 8) {
  const hop = (i) => `Hop ${i}/${total}`;
  if (t.asyncJob) {
    const worker = snapshot.workerQueue?.workerAddress ?? '10.41';
    return [
      `${hop(1)}: Browser (${from}) emits "${t.displayRequest ?? t.request}"`,
      `${hop(2)}: Network (10.x) routes to LoadBalancer (${serverAddress})`,
      `${hop(3)}: LoadBalancer (${serverAddress}) -> ${target} queue`,
      `${hop(4)}: WebServer (${target}) enqueues job to WorkerQueue (10.40)`,
      `${hop(5)}: WebServer (${target}) -> "202 Accepted"`,
      `${hop(6)}: Network delivers 202 response to ${from}`,
      `${hop(7)}: Browser (${from}) received and displayed 202 Accepted`,
      `${hop(8)}: Worker (${worker}) processed job and committed to Database (10.30)`,
    ];
  }
  // Requests served synchronously keep the Stage 4 cache/database story;
  // the worker does not see them, so the tail hop reads idle.
  const worker = snapshot.workerQueue?.workerAddress ?? '10.41';
  const db = snapshot.database ?? {};
  const primary = db.primaryAddress ?? '10.30';
  const replica = db.replicaAddress ?? '10.31';
  const lag = db.replicationLagTicks ?? 3;
  const dbOp =
    t.dbOp === 'WRITE'
      ? `Database WRITE @ Primary (${primary}) — replica lags ${lag}t`
      : t.dbOp === 'SELECT' && t.dbStale
        ? `Database SELECT @ Replica (${replica}) — STALE (lag ${lag}t)`
        : t.dbOp === 'SELECT'
          ? `Database SELECT @ Replica (${replica}) — fresh`
          : `Database SKIP — warm cache HIT (${snapshot.cache?.address ?? '10.20'})`;
  return [
    `${hop(1)}: Browser (${from}) emits "${t.displayRequest ?? t.request}"`,
    `${hop(2)}: Network (10.x) routes to LoadBalancer (${serverAddress})`,
    `${hop(3)}: LoadBalancer (${serverAddress}) -> ${target} queue`,
    `${hop(4)}: ${dbOp}`,
    `${hop(5)}: WebServer (${target}) -> "${t.response}" (cache ${t.cacheStatus})`,
    `${hop(6)}: Network delivers ${t.status} response to ${from}`,
    `${hop(7)}: Browser (${from}) received and displayed ${t.status}`,
    `${hop(8)}: Worker (${worker}) idle — no async jobs in this trace`,
  ];
}

function hopSentences(stage, snapshot, from, serverAddress) {
  const t = snapshot.trace ?? {};
  const target = t.targetServer ?? '10.11';
  if (stage === 6) {
    const dnsAddress = snapshot.dns?.address ?? '10.60';
    // PINS: an unknown host answers NX — the trace is the DNS ask plus the
    // `NX no record` answer, then the browser renders the NX card; no GET
    // hop appears anywhere in the sentence list (model-stage6 test).
    if (t.status === 'NX') {
      return [
        `Hop 1/4: Browser (${from}) emits "${t.displayRequest ?? t.request}"`,
        `Hop 2/4: Browser (${from}) asks DNS (${dnsAddress}) for ${t.host}`,
        `Hop 3/4: DNS (${dnsAddress}) -> ${from} | NX no record`,
        `Hop 4/4: Browser (${from}) renders NX no record — no GET emitted`,
      ];
    }
    const total = t.totalHops ?? 8;
    const base = stage5Chain(t, snapshot, from, serverAddress, target, total);
    // PINS: a host-less Stage 6 path (`GET /about`) keeps the Stage 5 hop
    // count and hop texts byte-identical — no DNS hop, no cross-subnet hop.
    if (!t.host) return base;
    // Hosted path: exactly the Stage 5 chain plus the two DNS hops that
    // resolved the host (ask, then the answer the ledger actually gave).
    return [
      base[0],
      `Hop 2/${total}: Browser (${from}) asks DNS (${dnsAddress}) for ${t.host}`,
      `Hop 3/${total}: DNS (${dnsAddress}) -> ${from} | ${t.host} = ${t.dnsTarget} (cache ${t.dnsCacheStatus})`,
      ...base.slice(1),
    ];
  }
  if (stage === 5) {
    return stage5Chain(t, snapshot, from, serverAddress, target);
  }

