// DOCUMENTS: Stage 5 worker-queue jobs render one row per pending job with
// its enqueue tick; the queue stats and worker HUD mirror the counters and
// the active job (DESIGN.md queue-jobs-list).
function renderJobsInto(container, jobs) {
  container.replaceChildren(
    ...jobs.map((job) => {
      const item = document.createElement('li');
      item.className = 'route-item';
      item.textContent = `#${job.jobId} · ${job.path} · queued @ tick ${job.queuedAtTick}`;
      return item;
    }),
  );
}

// DOCUMENTS: Stage 6 DNS ledger rows — one row per live resolver-cache
// entry with its remaining TTL in ticks, next to the lookup/hit counters
// (DESIGN.md #dns-entries-list).
function renderDnsEntries(entries) {
  els.dnsEntries.replaceChildren(
    ...entries.map((e) => {
      const item = document.createElement('li');
      item.className = 'route-item';
      item.textContent = `${e.name} = ${e.target} · ttl ${e.ttlRemaining}t`;
      return item;
    }),
  );
}

// DOCUMENTS: the Network card's mini-IP interface table — Stage 6 adds the
// DNS resolver, the Router, and the router's 20.x side to the interfaces
// the crowd stages list; every row derives from the live snapshot stage.
function renderNetworkRows(snapshot) {
  const stage = snapshot.stage ?? 1;
  const rows =
    stage >= 6
      ? [
          ['10.1', 'LoadBalancer -> 10.11, 10.12'],
          ['10.2', 'Browser (You)'],
          ['10.2+', `${snapshot.users} browsers`],
          ['10.60', 'DNS'],
          ['10.65', 'Router'],
          ['20.1', 'Router (20.x side)'],
        ]
      : [
          ['10.1', stage >= 2 ? 'LoadBalancer -> 10.11, 10.12' : 'WebServer'],
          ['10.2', 'Browser (You)'],
          ['10.2+', 'browsers'],
        ];
  els.networkRows.replaceChildren(
    ...rows.map(([address, role]) => {
      const tr = document.createElement('tr');
      const td1 = document.createElement('td');
      td1.className = 'mono';
      td1.textContent = address;
      const td2 = document.createElement('td');
      td2.textContent = role;
      tr.replaceChildren(td1, td2);
      return tr;
    }),
  );
}

