// live stage 1-6 (6 became live with Stage 6a) and ?users=U clamps into the
// slider's 1-50 range; anything unknown, out of range, or non-numeric falls
// back to the fresh-load defaults (Stage 1, five users) without a console
// error. Named counter-example (pinned in e2e/panel.spec.js): ?stage=9
// renders Stage 1 — it must never select a pill or crash.
function readDeepLink() {
  const params = new URLSearchParams(window.location.search);
  const stage = Number.parseInt(params.get('stage') ?? '', 10);
  const users = Number.parseFloat(params.get('users') ?? '');
  return {
    stage: stage >= 1 && stage <= 6 ? stage : 1,
    users: Number.isFinite(users) ? Math.min(50, Math.max(1, Math.round(users))) : 5,
  };
}

